import React, { useState } from 'react';
import { Droplets, Check, X } from 'lucide-react';
import { milkService } from '../../services/api';
import toast from 'react-hot-toast';

/**
 * Hızlı Sağım Matrisi (Rapid Parlor Milk Entry Grid)
 * Sağımhanede tüm sağmalların sabah/öğle/akşam litrelerini tek ekranda topluca girmeyi sağlar.
 */
export default function RapidMilkingModal({ isOpen, onClose, animals = [], farmId, onSaved }) {
  const [recordDate, setRecordDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [session, setSession] = useState('Sabah'); // Sabah, Öğle, Akşam
  const [quantities, setQuantities] = useState({});
  const [saving, setSaving] = useState(false);

  if (!isOpen) return null;

  const femaleAnimals = animals.filter(a => a.gender === 'F');

  const handleQtyChange = (animalId, val) => {
    setQuantities(prev => ({
      ...prev,
      [animalId]: val
    }));
  };

  const handleSaveAll = async () => {
    const entries = Object.entries(quantities)
      .map(([animalId, qtyStr]) => {
        const qty = parseFloat(String(qtyStr).replace(',', '.'));
        return { animalId: parseInt(animalId, 10), quantity: qty };
      })
      .filter(item => !isNaN(item.quantity) && item.quantity > 0);

    if (entries.length === 0) {
      toast.error('Lütfen en az bir hayvan için süt miktarı girin.');
      return;
    }

    setSaving(true);
    let successCount = 0;
    let failCount = 0;

    try {
      await Promise.all(
        entries.map(async (entry) => {
          try {
            await milkService.create(farmId, {
              animal_id: entry.animalId,
              record_date: recordDate,
              record_time: session,
              quantity: entry.quantity,
              notes: 'Toplu sağım girişi'
            });
            successCount++;
          } catch {
            failCount++;
          }
        })
      );

      if (successCount > 0) {
        toast.success(`${successCount} hayvanın sağım kaydı kaydedildi.${failCount > 0 ? ` (${failCount} hatalı)` : ''}`);
        if (onSaved) onSaved();
        onClose();
      } else {
        toast.error('Kayıtlar işlenirken hata oluştu.');
      }
    } catch {
      toast.error('Toplu sağım sırasında hata oluştu.');
    } finally {
      setSaving(false);
    }
  };

  const totalLitres = Object.values(quantities).reduce((acc, curr) => {
    const n = parseFloat(String(curr).replace(',', '.'));
    return acc + (isNaN(n) ? 0 : n);
  }, 0);

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-xs z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in">
        {/* Modal Başlığı */}
        <div className="p-5 border-b border-gray-100 flex items-center justify-between bg-blue-50/70">
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-blue-600 text-white rounded-xl shadow-xs">
              <Droplets className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-bold text-gray-900 text-base">Hızlı Sağımhane Matrisi</h3>
              <p className="text-xs text-blue-700">Tüm sağmalların sütlerini tek tıkla topluca kaydedin</p>
            </div>
          </div>
          <button onClick={onClose} className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 hover:bg-white transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Ayarlar Çubuğu */}
        <div className="p-4 bg-gray-50 border-b border-gray-100 flex flex-wrap items-center justify-between gap-3 text-xs">
          <div className="flex items-center gap-2">
            <label className="font-bold text-gray-600">Sağım Tarihi:</label>
            <input
              type="date"
              value={recordDate}
              onChange={e => setRecordDate(e.target.value)}
              className="px-2.5 py-1.5 rounded-lg border border-gray-200 bg-white font-medium"
            />
          </div>

          <div className="flex items-center gap-1.5">
            <span className="font-bold text-gray-600 mr-1">Sağım Vakti:</span>
            {['Sabah', 'Öğle', 'Akşam'].map(s => (
              <button
                key={s}
                type="button"
                onClick={() => setSession(s)}
                className={`px-3 py-1 rounded-lg font-bold transition-all ${
                  session === s
                    ? 'bg-blue-600 text-white shadow-xs'
                    : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-100'
                }`}
              >
                {s}
              </button>
            ))}
          </div>

          <div className="text-right">
            <span className="text-gray-500 font-medium">Toplam: </span>
            <strong className="text-blue-700 text-sm font-black">{totalLitres.toFixed(1)} L</strong>
          </div>
        </div>

        {/* Hayvan Tablosu */}
        <div className="flex-1 overflow-y-auto p-4 max-h-96 divide-y divide-gray-100 scrollbar-thin">
          {femaleAnimals.length === 0 ? (
            <div className="text-center py-10 text-gray-400 text-xs">
              Kayıtlı dişi hayvan bulunamadı.
            </div>
          ) : (
            femaleAnimals.map(a => (
              <div key={a.id} className="py-2.5 flex items-center justify-between gap-3 hover:bg-gray-50/80 px-2 rounded-xl transition-colors">
                <div className="min-w-0 flex-1">
                  <p className="font-bold text-sm text-gray-800 truncate">{a.name}</p>
                  <p className="text-[11px] text-gray-400 font-mono">{a.code} • {a.breed || a.species}</p>
                </div>

                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    step="0.1"
                    min="0"
                    placeholder="0.0"
                    value={quantities[a.id] || ''}
                    onChange={e => handleQtyChange(a.id, e.target.value)}
                    className="w-24 text-right px-3 py-1.5 rounded-xl border border-gray-200 text-sm font-black text-gray-900 focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                  <span className="text-xs font-bold text-gray-400 w-4">L</span>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Alt Kısım ve Kaydet */}
        <div className="p-4 bg-gray-50 border-t border-gray-100 flex items-center justify-between">
          <span className="text-xs text-gray-500 font-medium">
            {Object.keys(quantities).length} hayvana değer girildi
          </span>
          <div className="flex gap-2">
            <button type="button" onClick={onClose} className="btn-secondary text-xs px-4 py-2">
              İptal
            </button>
            <button
              type="button"
              disabled={saving}
              onClick={handleSaveAll}
              className="btn-primary text-xs px-5 py-2 bg-blue-600 hover:bg-blue-700 shadow-sm flex items-center gap-1.5"
            >
              {saving ? 'Kaydediliyor...' : <><Check className="w-4 h-4" /> Tümünü Kaydet</>}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
